import { useMemo } from 'react';

type P = '_' | 'R' | 'O' | 'Y' | 'G' | 'B' | 'K' | 'W';

const COLORS: Record<P, string | null> = {
  _: null, R: '#ff4444', O: '#ff8800', Y: '#ffcc00',
  G: '#44cc44', B: '#4488ff', K: '#333333', W: '#cccccc',
};

// Fire obstacle (8x8)
const FIRE: P[][] = [
  ['_','_','_','Y','Y','_','_','_'],
  ['_','_','Y','O','O','Y','_','_'],
  ['_','Y','O','R','R','O','Y','_'],
  ['_','Y','R','R','R','R','Y','_'],
  ['Y','O','R','R','R','R','O','Y'],
  ['Y','O','R','R','R','R','O','Y'],
  ['_','Y','O','R','R','O','Y','_'],
  ['_','_','Y','O','O','Y','_','_'],
];

// Spike obstacle (8x8)
const SPIKE: P[][] = [
  ['_','_','_','W','W','_','_','_'],
  ['_','_','_','W','W','_','_','_'],
  ['_','_','W','K','K','W','_','_'],
  ['_','_','W','K','K','W','_','_'],
  ['_','W','K','K','K','K','W','_'],
  ['_','W','K','K','K','K','W','_'],
  ['W','K','K','K','K','K','K','W'],
  ['W','K','K','K','K','K','K','W'],
];

// Cactus (8x12)
const CACTUS: P[][] = [
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','G','_','G','G','_','G','_'],
  ['_','G','G','G','G','G','G','_'],
  ['_','G','G','G','G','G','G','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
  ['_','_','_','G','G','_','_','_'],
];

// Bomb (8x8)
const BOMB: P[][] = [
  ['_','_','_','Y','_','_','_','_'],
  ['_','_','Y','O','_','_','_','_'],
  ['_','_','_','K','K','_','_','_'],
  ['_','_','K','K','K','K','_','_'],
  ['_','K','K','K','K','K','K','_'],
  ['_','K','K','W','K','K','K','_'],
  ['_','K','K','K','K','K','K','_'],
  ['_','_','K','K','K','K','_','_'],
];

// Rock (8x6)
const ROCK: P[][] = [
  ['_','_','_','W','W','_','_','_'],
  ['_','_','W','K','K','W','_','_'],
  ['_','W','K','K','K','K','W','_'],
  ['W','K','K','W','K','K','K','W'],
  ['W','K','K','K','K','K','K','W'],
  ['W','K','K','K','K','K','K','W'],
];

export type ObstacleType = 'fire' | 'spike' | 'cactus' | 'bomb' | 'rock';

const OBSTACLE_MAP: Record<ObstacleType, P[][]> = {
  fire: FIRE, spike: SPIKE, cactus: CACTUS, bomb: BOMB, rock: ROCK,
};

export const OBSTACLE_TYPES: ObstacleType[] = ['fire', 'spike', 'cactus', 'bomb', 'rock'];

interface PixelObstacleProps {
  type: ObstacleType;
  size?: number;
  style?: React.CSSProperties;
  className?: string;
}

export function PixelObstacle({ type, size = 32, style, className }: PixelObstacleProps) {
  const grid = OBSTACLE_MAP[type];
  const rows = grid.length;
  const cols = grid[0].length;

  const pixels = useMemo(() => {
    const result: { x: number; y: number; color: string }[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const color = COLORS[grid[r][c]];
        if (color) result.push({ x: c, y: r, color });
      }
    }
    return result;
  }, [grid, rows, cols]);

  return (
    <svg
      width={size}
      height={size * (rows / cols)}
      viewBox={`0 0 ${cols} ${rows}`}
      style={{ imageRendering: 'pixelated', ...style }}
      className={className}
    >
      {pixels.map((p, i) => (
        <rect key={i} x={p.x} y={p.y} width={1} height={1} fill={p.color} />
      ))}
    </svg>
  );
}
